WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true ORDER BY "s"."id" ASC NULLS LAST LIMIT 50000 ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , "c2"."j" AS "author" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t0"."author_id" LIMIT 1 ) AS "t1" ) AS "c2" ON true
